<?php
require_once 'funciones.php'; exigir_login(); if(($_SESSION['rol']??'')!=='cliente'||$_SERVER['REQUEST_METHOD']!=='POST'){header('Location: tienda.php');exit;}
$direccion=trim($_POST['direccion']??'');$envio=(int)($_POST['envio_id']??0);$pago=(int)($_POST['pago_id']??0);$cart=$_SESSION['carrito']??[];if($direccion===''||!$cart){aviso('Completa los datos del pedido.','error');header('Location: checkout.php');exit;}
$q=$conn->prepare('SELECT costo FROM metodos_envio WHERE id=? AND activo=1');$q->bind_param('i',$envio);$q->execute();$env=$q->get_result()->fetch_assoc();$q=$conn->prepare('SELECT id FROM metodos_pago WHERE id=? AND activo=1');$q->bind_param('i',$pago);$q->execute();$pay=$q->get_result()->fetch_assoc();if(!$env||!$pay){aviso('Selecciona un método de envío y pago válido.','error');header('Location: checkout.php');exit;}
$conn->begin_transaction();try{$detalles=[];$subtotal=0;foreach($cart as $id=>$cant){$id=(int)$id;$cant=max(1,min(20,(int)$cant));$q=$conn->prepare('SELECT id,nombre,precio FROM productos WHERE id=? AND activo=1 FOR UPDATE');$q->bind_param('i',$id);$q->execute();$p=$q->get_result()->fetch_assoc();if(!$p)continue;$detalles[]=[$p,$cant];$subtotal+=(float)$p['precio']*$cant;}if(!$detalles)throw new Exception('No hay productos disponibles.');$total=$subtotal+(float)$env['costo'];$uid=(int)$_SESSION['usuario_id'];$q=$conn->prepare('INSERT INTO pedidos(usuario_id,total,direccion,metodo_pago_id,metodo_envio_id) VALUES(?,?,?,?,?)');$q->bind_param('idsii',$uid,$total,$direccion,$pago,$envio);$q->execute();$pedido=(int)$conn->insert_id;$q=$conn->prepare('INSERT INTO pedido_detalles(pedido_id,producto_id,nombre_producto,precio,cantidad) VALUES(?,?,?,?,?)');foreach($detalles as [$p,$cant]){$pid=(int)$p['id'];$nombre=$p['nombre'];$precio=(float)$p['precio'];$q->bind_param('iisdi',$pedido,$pid,$nombre,$precio,$cant);$q->execute();}$conn->commit();$_SESSION['carrito']=[];$_SESSION['ultimo_pedido']=$pedido;header('Location: pedido_exito.php');exit;}catch(Throwable $ex){$conn->rollback();aviso('No se pudo guardar el pedido: '.$ex->getMessage(),'error');header('Location: carrito.php');exit;}
